window.AUTH=window.AUTH||{};window.AUTH["22-381"]={"d":"22-381","id":"2022/22-381","n":"Yegiazaryan v. Smagin","briefs":[{"k":"petitioner","label":"Brief of petitioners","date":"2023-02-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-381/255679/20230227155919431_22-381%20Brief.pdf","side":"pet","n":84},{"k":"respondent","label":"Brief of respondent Vitaly Smagin","date":"2023-03-29","url":"https://www.supremecourt.gov/DocketPDF/22/22-381/260155/20230329120918993_22-381%2022-383%20Smagin%20Respondent%20Merit%20Brief.pdf","side":"res","n":43},{"k":"reply","label":"Reply of petitioners","date":"2023-04-14","url":"https://www.supremecourt.gov/DocketPDF/22/22-381/263477/20230414085943817_22-381%20and%2022-383%20Reply%20Brief.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r43_jhek.pdf","tr":true,"items":[{"t":"case","label":"Agency Holding Corp. v. Malley-Duff & Assocs., Inc.","cite":"483 U.S. 143","y":1987,"id":"1986/86-497","sc":1,"by":{"0":"18, 21, 26, 51","2":"6"}},{"t":"case","label":"Alabama Great S. R.R. v. Carroll","cite":"11 So. 803","y":1892,"court":"Ala.","url":"https://www.courtlistener.com/c/So./11/803/","by":{"0":"35, 55"},"q":[{"src":"argument","who":"Mr. Levy","text":"We cite the great Alabama case from 1898, an Alabama decision interpreting an Alabama state statute, and it says that -- that case concerned negligent conduct that occurred in Alabama and an injury in Tennessee, and it said that read into the statute is a presumption that the statute covers only injuries in Alabama, and for injuries in Mississippi, you have to look to the state of -- the state law of Mississippi."}]},{"t":"case","label":"Albert Levine Assocs. v. Bertoni & Cotti","cite":"314 F. Supp. 169","y":1970,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./314/169/","by":{"0":"36"}},{"t":"case","label":"American Banana Co. v. United Fruit Co.","cite":"213 U.S. 347","y":1909,"id":"scdb/1908-135","sc":1,"by":{"0":"32, 39","2":"3-4"}},{"t":"case","label":"Anza v. Ideal Steel Supply Corp.","cite":"547 U.S. 451","y":2006,"id":"2005/04-433","sc":1,"by":{"0":"15, 27, 28"},"q":[{"src":"brief","b":0,"text":"[t]he Court unanimously recognized in Sedima that one reason— and, for the dissent, the principal reason—Congress enacted RICO was to protect businesses against competitive injury from organized crime.","cite":"547 U.S. 451, 473"},{"src":"brief","b":0,"text":"‘creates civil remedies for the honest businessman who has been damaged by unfair competition from the racketeer businessman.’","cite":"547 U.S. at 473"}]},{"t":"case","label":"Arellano v. McDonough","cite":"143 S. Ct. 543","y":2023,"id":"2022/21-432","sc":1,"by":{"0":"19"}},{"t":"case","label":"Armada (Sing.) PTE Ltd. v. Amcol Int’l Corp.","cite":"885 F.3d 1090","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/1090/","by":{"0":"13, 37, 43","1":"36, 37, 38, 39","2":"11"}},{"t":"case","label":"Associated Gen. Contractors of Cal., Inc. v. California State Council of Carpenters","cite":"459 U.S. 519","y":1983,"id":"1982/81-334","sc":1,"by":{"0":"24, 25"},"q":[{"src":"brief","b":0,"text":"adopted * * * the judicial gloss","cite":"459 U.S. at 4"}]},{"t":"case","label":"Beck v. Prupis","cite":"529 U.S. 494","y":2000,"id":"1999/98-1480","sc":1,"by":{"0":"15, 30","2":"7, 9"},"q":[{"src":"brief","b":0,"text":"time of RICO’s enactment in 1970,","cite":"529 U.S. 494, 500-501"},{"src":"brief","b":0,"text":"time of RICO’s enactment in 1970.","cite":"529 U.S. 494, 500-501"},{"src":"argument","who":"Mr. Levy","text":"One, as Beck instructs, the Court should look at the common law at the time of RICO's enactment, which here is 1970. The Second Restatement was passed or -- or came into formal form in 1972, I believe."}]},{"t":"case","label":"Blodgett v. Silberman","cite":"277 U.S. 1","y":1928,"id":"scdb/1927-097","sc":1,"by":{"0":"41, 45","2":"10"},"q":[{"src":"argument","who":"Mr. Levy","text":"Blodgett makes the point in 1928, and the principle goes back to Justice Story's Commentaries that -- that a property right that is intangible, such as a debt, follows the creditor."},{"src":"argument","who":"Mr. Levy","text":"And this directly contravenes what the Court -- this Court said in Blodgett, that funds in a bank account create a claim against the bank, which is a chosen action and an intangible."}]},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"0":"23"}},{"t":"case","label":"Cassirer v. Thyssen-Bornemisza Collection Found.","cite":"142 S. Ct. 1502","y":2022,"id":"2021/20-1566","sc":1,"by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"a means of selecting which jurisdiction’s law governs the determination of liability.","cite":"142 S. Ct. 1502, 1507"}]},{"t":"case","label":"Cevdet Aksut Ve Ogullari Koll.Sti v. Cavusoglu","cite":"756 F. App’x 119","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/756/119/","by":{"0":"51","2":"19"},"q":[{"src":"argument","who":"Mr. Levy","text":"The Ninth Circuit purported to apply the same test as the Third Circuit, and yet those two circuits split on nearly identical facts in Cevdet and the decision below."},{"src":"argument","who":"Mr. Levy","text":"Of -- of whether -- well, in Cevdet, the Third Circuit looked at basically the same facts. There was a judgment that was unpaid. It was here."}]},{"t":"case","label":"Chattanooga Foundry & Pipe Works v. City of Atlanta","cite":"203 U.S. 390","y":1906,"id":"scdb/1906-040","sc":1,"by":{"0":"14, 21-23, 26, 29, 42","1":"28, 29","2":"2, 5"},"q":[{"src":"brief","b":0,"text":"object [which is] capable of injury","cite":"203 U.S. at 399"},{"src":"brief","b":0,"text":"unless the harm fell upon some object more definite and less ideal than his total wealth.","cite":"203 U.S. at 399"},{"src":"argument","who":"Mr. Levy","text":"Well, it's what Congress intended, and it's rooted in the -- in the text of the statute, which protect -- protects injuries to the person of the plaintiff and allows the person of the plaintiff to sue for threefold his damages if injured, and -- and in the case of Chattanooga Foundry, which was decided soon after the enactment of the Sherman Act -- the Sherman Act was enacted in 1890, Chattanooga Foundry in the early 1900s -- Justice Holmes for the Court wrote that we do not go behind the person of the plaintiff."},{"src":"argument","who":"Justice Jackson","text":"And you said -- but you -- you -- the common law that you're focusing on is the Chat -- Chattanooga case?"},{"src":"argument","who":"Mr. Levy","text":"No, Chattanooga we're focusing on to interpret the words of the statute. The common law, we -- we look at two sources of the common law. One is common law conflict rules as reflected in the First Restatement, and the reason we look at those is because the common law looked to the situs of an injury to determine which law applied and -- and -- and had a rule for determining where an economic injury occurred, and for that reason, we look to the First Restatement rule, which was the majority rule at the time of RICO's enactment."}]},{"t":"case","label":"Chicago, R. I. & P. R. Co. v. Sturm","cite":"174 U.S. 710","y":1899,"id":"scdb/1898-173","sc":1,"by":{"0":"46"},"q":[{"src":"argument","who":"Mr. Levy","text":"That's reflected in Justice Story. That's reflected in some of the enforcement cases that the Court looked at, Chicago Rail versus Sturm, Harris versus Balk."}]},{"t":"case","label":"CMACO Auto. Sys., Inc. v. Wanxiang Am. Corp.","cite":"589 F.3d 235","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/589/235/","by":{"0":"37","1":"36, 38"}},{"t":"case","label":"Commodities & Mins. Enter. Ltd. v. CVG Ferominera Orinoco, C.A.","cite":"49 F.4th 802","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/49/802/","by":{"0":"53"}},{"t":"case","label":"Cox v. Roth","cite":"348 U.S. 207","y":1955,"id":"scdb/1954-022","sc":1,"by":{"0":"31"}},{"t":"case","label":"Curry v. McCanless","cite":"307 U.S. 357","y":1939,"id":"scdb/1938-084","sc":1,"by":{"0":"45"}},{"t":"case","label":"Daimler AG v. Bauman","cite":"571 U.S. 117","y":2014,"id":"2013/11-965","sc":1,"by":{"0":"19, 48, 56"}},{"t":"case","label":"E.E.O.C. v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"by":{"0":"33, 34"}},{"t":"case","label":"Engine Specialties, Inc. v. Bombardier Ltd.","cite":"605 F.2d 1","y":1979,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/605/1/","by":{"0":"37","1":"36, 38"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"by":{"0":"49, 50, 55","1":"16, 17, 18, 41","2":"16-17, 19-20"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"by":{"0":"31"}},{"t":"case","label":"Graham v. General U.S. Grant Post No. 2665, V. F. W.","cite":"248 N.E.2d 657","y":1969,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/248/657/","by":{"0":"34"}},{"t":"case","label":"Haaksman v. Diamond Offshore (Berm.), Ltd.","cite":"260 S.W.3d 476","y":2008,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.3d/260/476/","by":{"0":"54"}},{"t":"case","label":"Harris v. Balk","cite":"198 U.S. 215","y":1905,"id":"scdb/1904-083","sc":1,"by":{"0":"46","2":"11"},"q":[{"src":"argument","who":"Mr. Levy","text":"That's reflected in Justice Story. That's reflected in some of the enforcement cases that the Court looked at, Chicago Rail versus Sturm, Harris versus Balk."}]},{"t":"case","label":"Hartford Fire Ins. Co. v. California","cite":"509 U.S. 764","y":1993,"id":"1992/91-1111","sc":1,"by":{"0":"33, 48"},"q":[{"src":"brief","b":0,"text":"the respect sovereign nations afford each other by limiting the reach of their laws.","cite":"509 U.S. 764, 817"},{"src":"argument","who":"Mr. Levy","text":"Justice Scalia made that very clear in his dissent in Hartford Fire. And -- and the Court has made that clear for the Court as a whole, including in RJR, where -- that it -- that it was applying the presumption as a matter of interpreting the statute wholly apart from comity."}]},{"t":"case","label":"Hawaii v. Standard Oil Co.","cite":"405 U.S. 251","y":1972,"id":"1971/70-49","sc":1,"by":{"0":"26"}},{"t":"case","label":"Hertz Corp v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"[s]imple * * * rules * * * promote greater predictability.","cite":"559 U.S. 77, 94-95"}]},{"t":"case","label":"Holmes v. Securities Inv. Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"by":{"0":"14, 23-25, 31"},"q":[{"src":"brief","b":0,"text":"[w]e may fairly credit the 91st Congress, which enacted RICO, with knowing the interpretation federal courts had given the words earlier Congresses had used first in § 7 of the Sherman Act, and later in the Clayton Act’s § 4.","cite":"503 U.S. at 268"},{"src":"brief","b":0,"text":"and we can only assume [Congress] intended them to have the same meaning that courts had already given them.","cite":"503 U.S. at 268"},{"src":"argument","who":"Mr. Levy","text":"Well, it's what Congress intended, and it's rooted in the -- in the text of the statute, which protect -- protects injuries to the person of the plaintiff and allows the person of the plaintiff to sue for threefold his damages if injured, and -- and in the case of Chattanooga Foundry, which was decided soon after the enactment of the Sherman Act -- the Sherman Act was enacted in 1890, Chattanooga Foundry in the early 1900s -- Justice Holmes for the Court wrote that we do not go behind the person of the plaintiff."}]},{"t":"case","label":"Humphrey v. GlaxoSmithKline PLC","cite":"905 F.3d 694","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/905/694/","by":{"0":"13, 51"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"the ease with which [petitioners'] bright-line rule can be applied gives it some surface appeal,","cite":"905 F. 3d, at 709"}]},{"t":"case","label":"J. McIntyre Mach., Ltd. v. Nicastro","cite":"564 U.S. 873","y":2011,"id":"2010/09-1343","sc":1,"by":{"0":"32","1":"32"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"As with any question of statutory interpretation, [the] analysis begins with the plain language of the statute.","cite":"555 U.S. 113, 118"}]},{"t":"case","label":"Kamel v. Hill-Rom Co., Inc.","cite":"108 F.3d 799","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/108/799/","by":{"0":"37","1":"38"}},{"t":"case","label":"Kirtland v. Hotchkiss","cite":"100 U.S. 491","y":1879,"id":"scdb/1879-018","sc":1,"by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"debt, although a species of intangible property, may, for purposes of taxation, if not for all others, be regarded as situated at the domicile of the creditor.","cite":"100 U.S. 491, 498"}]},{"t":"case","label":"Klehr v. A.O. Smith Corp.","cite":"521 U.S. 179","y":1997,"id":"1996/96-663","sc":1,"by":{"0":"23","2":"5"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"0":"25"}},{"t":"case","label":"Lenchyshyn v. Pelko Elec., Inc.","cite":"723 N.Y.S.2d 285","y":2001,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/723/285/","by":{"0":"53"}},{"t":"case","label":"Marmon v. Mustang Aviation, Inc.","cite":"430 S.W.2d 182","y":1968,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/430/182/","by":{"0":"34"}},{"t":"case","label":"Miller Bros. Co. v. Maryland","cite":"347 U.S. 340","y":1954,"id":"scdb/1953-058","sc":1,"by":{"0":"45"}},{"t":"case","label":"Mississippi Band of Choctaw Indians v. Holyfield","cite":"490 U.S. 30","y":1989,"id":"1988/87-980","sc":1,"by":{"0":"19"},"q":[{"src":"argument","who":"Mr. Levy","text":"We cite the great Alabama case from 1898, an Alabama decision interpreting an Alabama state statute, and it says that -- that case concerned negligent conduct that occurred in Alabama and an injury in Tennessee, and it said that read into the statute is a presumption that the statute covers only injuries in Alabama, and for injuries in Mississippi, you have to look to the state of -- the state law of Mississippi."}]},{"t":"case","label":"Mitchell v. United States","cite":"88 U.S. 350","y":1874,"id":"scdb/1874-104","sc":1,"by":{"0":"29"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"0":"30"}},{"t":"case","label":"Morrison v. National Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"by":{"0":"6, 25, 32, 34, 52","2":"17, 21"},"q":[{"src":"brief","b":0,"text":"[w]hen a statute has no clear indication of an extraterritorial application, it has none.","cite":"561 U.S. 247, 255"},{"src":"brief","b":0,"text":"[b]ut the presumption against extraterritorial application would be a craven watchdog indeed if it retreated to its kennel whenever some domestic activity is involved in the case.","cite":"561 U.S. at 266"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"represents a canon of construction, or a presumption about a statute's meaning, rather than a limit upon Congress's power to legislate.","cite":"561 U. S. 247, 255"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"preserv[es] a stable background against which Congress can legislate with predictable effects.","cite":"561 U. S., at 261"},{"src":"argument","who":"Mr. Kennedy","text":"RJR focus -- applied the presumption against extraterritoriality, just as Morrison did, just as Kiobel did. That's always been conduct-focused."},{"src":"argument","who":"Mr. Kennedy","text":"That is the exact same test that was set forth in RJR Nabisco when looking at extraterritoriality, and it's the test this Court has used consistently, Kiobel, Nestle, going back to Morrison, looking at the statute that is the --"},{"src":"argument","who":"Mr. Kennedy","text":"That's a long line of cases, again, going back to, you know, Morrison through RJR Nabisco that tells us conduct is the primary focus. So it's -- it's -- it's our precedent versus -- plus our statute that tells us to look at conduct first, but in this specific circumstance --"}]},{"t":"case","label":"Negonsott v. Samuels","cite":"507 U.S. 99","y":1993,"id":"1992/91-5397","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"task * * * to give effect to the will of Congress, and where its will has been expressed in reasonably plain terms, that language must ordinarily be regarded as conclusive.","cite":"507 U.S. 99, 104"}]},{"t":"case","label":"Nestlé USA, Inc. v. Doe","cite":"141 S. Ct. 1931","y":2021,"id":"2020/19-416","sc":1,"by":{"0":"48","1":"19","2":"16"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"0":"20"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"by":{"0":"16, 42"}},{"t":"case","label":"Perkins v. Benguet Consol. Mining Co.","cite":"342 U.S. 437","y":1952,"id":"scdb/1951-048","sc":1,"by":{"0":"56"}},{"t":"case","label":"Pfizer, Inc. v. Government of India","cite":"434 U.S. 308","y":1978,"id":"1977/76-749","sc":1,"by":{"0":"24, 38"},"q":[{"src":"brief","b":0,"text":"Section 7 of the Sherman Act was repealed in 1955 as redundant","cite":"434 U.S. 308, 311 n.8"}]},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"by":{"0":"28"},"q":[{"src":"argument","who":"Mr. Levy","text":"It's been interpreted in that way, starting from Chattanooga Foundry, the time the Sherman Act was enacted, and again through cases such as Reiter, which relied on -- on Chattanooga Foundry to interpret the antitrust laws in 1979 and agency holding."}]},{"t":"case","label":"Republic of Argentina v. NML Cap., Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"by":{"0":"54"}},{"t":"case","label":"Richards v. United States","cite":"369 U.S. 1","y":1962,"id":"1961/59","sc":1,"by":{"0":"31","1":"31, 32","2":"8"},"q":[{"src":"brief","b":0,"text":"[t]he general conflict-oflaws rule, followed by a vast majority of the States, [wa]s to apply the law of the place of injury to the substantive rights of the parties.","cite":"369 U.S. 1, 11-12"}]},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"by":{"0":"1-7, 12, 18-19, 32, 38-39, 48","1":"1-3, 10-16, 18, 20, 22, 24-26, 29-30, 36-38, 41-43","2":"1-3, 4, 6, 8-9, 13-16, 19-20"},"q":[{"src":"brief","b":0,"text":"defines ‘racketeering activity’ to encompass dozens of state and federal offenses, known in RICO parlance as predicates.","cite":"579 U.S. at 329"},{"src":"brief","b":0,"text":"A predicate offense implicates RICO when it is part of a ‘pattern of racketeering activity’— a series of related predicates that together demonstrate the existence or threat of continued criminal activity.","cite":"579 U.S. at 330"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"fail[ed] to adequately plead a domestic injury,","cite":"579 U. S., at 346"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"runs its own risks of generating international discord,","cite":"579 U. S., at 361"},{"src":"argument","who":"Mr. Levy","text":"Chief Justice, and may it please the Court: In RJR Nabisco, the Court held that private plaintiffs may sue under civil RICO for treble damages if they suffer a domestic injury."},{"src":"argument","who":"Mr. Levy","text":"Some -- certainly, some of the conduct can be here or abroad, and that's -- that's part three of Nabisco, which spoke of the substantive reach of RICO."},{"src":"argument","who":"Mr. Levy","text":"So it's a separate check that a plaintiff has to go through under civil RICO in light of the Court's instructions in RJR Nabisco, again, recognizing that providing a remedy raises wholly distinct issues, also recognizing that the right of action could be and was narrower than the substantive scope of RICO, and the Court did this analysis in RJR."}]},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"by":{"0":"51"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"4, 27, 28"},"q":[{"src":"brief","b":0,"text":"organized crime’s infiltration of legitimate enterprises","cite":"464 U.S. 16, 26"},{"src":"brief","b":0,"text":"the economic well-being of the Nation,","cite":"464 U.S. at 27"}]},{"t":"case","label":"Sack v. Low","cite":"478 F.2d 360","y":1973,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/478/360/","by":{"0":"15, 35, 36","2":"7"},"q":[{"src":"brief","b":0,"text":"deemed to be suffered where its economic impact is felt, normally the plaintiff’s residence.","cite":"478 F.2d 360, 366"}]},{"t":"case","label":"SCO Grp., Inc. v. International Bus. Machs. Corp.","cite":"879 F.3d 1062","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/879/1062/","by":{"0":"37"}},{"t":"case","label":"Sedima, S.P.R.L. v. Imrex Co.","cite":"473 U.S. 479","y":1985,"id":"1984/84-648","sc":1,"by":{"0":"27, 28","1":"16, 40"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"by":{"0":"46"},"q":[{"src":"argument","who":"Mr. Levy","text":"And, of course, Shaffer -- Shaffer itself, in Footnote 36, states that personal jurisdiction doesn't apply in -- in the enforcement proceedings."}]},{"t":"case","label":"Shapiro v. United States","cite":"335 U.S. 1","y":1948,"id":"scdb/1947-110","sc":1,"by":{"0":"15, 25"},"q":[{"src":"brief","b":0,"text":"and made [that] a part of the [RICO] enactment.","cite":"335 U.S. 1, 16"}]},{"t":"case","label":"Sinatra v. National Enquirer, Inc.","cite":"854 F.2d 1191","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/854/1191/","by":{"0":"37"}},{"t":"case","label":"Slater v. Mexican Nat’l R.R.","cite":"194 U.S. 120","y":1904,"id":"scdb/1903-145","sc":1,"by":{"0":"32"}},{"t":"case","label":"Spector v. Norwegian Cruise Lines Ltd.","cite":"545 U.S. 119","y":2005,"id":"2004/03-1388","sc":1,"by":{"0":"52"}},{"t":"case","label":"Tafflin v. Levitt","cite":"493 U.S. 455","y":1990,"id":"1989/88-1650","sc":1,"by":{"0":"36"}},{"t":"case","label":"Texas v. New Jersey","cite":"379 U.S. 674","y":1965,"id":"1964/13_orig","sc":1,"by":{"0":"16, 44, 45, 46","2":"11"},"q":[{"src":"brief","b":0,"text":"the old concept [that] intangible personal property is found at the domicile of its owner.","cite":"379 U.S. 674, 680-681"},{"src":"brief","b":0,"text":"a variation of the old concept of ‘mobilia sequuntur personam,’ according to which intangible personal property is found at the domicile of its owner.","cite":"379 U.S. 674, 680-681"},{"src":"argument","who":"Mr. Levy","text":"And in -- in Texas versus New Jersey, the Court was focusing on siting debts for purposes of escheatment, rejected a multifactor test that was proposed by one of the parties based on jurisdictional precedent, rejected the notion that it should look to the domicile of the debtor because that would have the odd result of changing -- turning a liability into -- looking at where a liability exists to site the asset."}]},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"by":{"0":"28"}},{"t":"case","label":"WesternGeco LLC v. ION Geophysical Corp.","cite":"138 S. Ct. 2129","y":2018,"id":"2017/16-1011","sc":1,"by":{"0":"6, 48"}},{"t":"case","label":"Weyerhauser Co. v. United States Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"by":{"0":"20"}},{"t":"case","label":"White v. Tennant","cite":"8 S.E. 596","y":1888,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E./8/596/","by":{"0":"19"}},{"t":"case","label":"ZF Auto. US, Inc. v. Luxshare, Ltd.","cite":"142 S. Ct. 2078","y":2022,"id":"2021/21-401","sc":1,"by":{"0":"48"}},{"t":"usc","label":"9 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/9/201","stext":{"head":"§201. Enforcement of Convention","paras":[[0,"The Convention on the Recognition and Enforcement of Foreign Arbitral Awards of June 10, 1958, shall be enforced in United States courts in accordance with this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/201?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 53","1":"34"}},{"t":"usc","label":"9 U.S.C. § 301-07","url":"https://www.law.cornell.edu/uscode/text/9/301-07","by":{"0":"53"}},{"t":"usc","label":"15 U.S.C. § 6a","url":"https://www.law.cornell.edu/uscode/text/15/6a","stext":{"head":"§6a. Conduct involving trade or commerce with foreign nations","paras":[[0,"Sections 1 to 7 of this title shall not apply to conduct involving trade or commerce (other than import trade or import commerce) with foreign nations unless—"],[1,"(1) such conduct has a direct, substantial, and reasonably foreseeable effect—"],[2,"(A) on trade or commerce which is not trade or commerce with foreign nations, or on import trade or import commerce with foreign nations; or"],[2,"(B) on export trade or export commerce with foreign nations, of a person engaged in such trade or commerce in the United States; and"],[1,"(2) such effect gives rise to a claim under the provisions of sections 1 to 7 of this title, other than this section."],[0,"If sections 1 to 7 of this title apply to such conduct only because of the operation of paragraph (1)(B), then sections 1 to 7 of this title shall apply to such conduct only for injury to export business in the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/6a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"49","1":"18"}},{"t":"usc","label":"15 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/15/15","by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"injured in his business or property.","cite":"15 U.S.C. 15"}]},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","subs":["(3)"],"stext":{"head":"§1961. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) \"racketeering activity\" means (A) any act or threat involving murder, kidnapping, gambling, arson, robbery, bribery, extortion, dealing in obscene matter, or dealing in a controlled substance or listed chemical (as defined in section 102 of the Controlled Substances Act), which is chargeable under State law and punishable by imprisonment for more than one year; (B) any act which is indictable under any of the following provisions of title 18, United States Code: Section 201 (relating to bribery), section 224 (relating to sports bribery), sections 471, 472, and 473 (relating to counterfeiting), section 659 (relating to theft from interstate shipment) if the act indictable under section 659 is felonious, section 664 (relating to embezzlement from pension and welfare funds), sections 891–894 (relating to extortionate credit transactions), section 932 (relating to straw purchasing), section 933 (relating to trafficking in firearms), section 1028 (relating to fraud and related activity in connection with identification documents), section 1029 (relating to fraud and related activity in connection with access devices), section 1084 (relating to the transmission of gambling information), section 1341 (relating to mail fraud), section 1343 (relating to wire fraud), section 1344 (relating to financial institution fraud), section 1351 (relating to fraud in foreign labor contracting), section 1425 (relating to the procurement of citizenship or nationalization unlawfully), section 1426 (relating to the reproduction of naturalization or citizenship papers), section 1427 (relating to the sale of naturalization or citizenship papers), sections 1461–1465 (relating to obscene matter), section 1503 (relating to obstruction of justice), section 1510 (relating to obstruction of criminal investigations), section 1511 (relating to the obstruction of State or local law enforcement), section 1512 (relating to tampering with a witness, victim, or an informant), section 1513 (relating to retaliating against a witness, victim, or an informant), section 1542 (relating to false statement in application and use of passport), section 1543 (relating to forgery or false use of passport), section 1544 (relating to misuse of passport), section 1546 (relating to fraud and misuse of visas, permits, and other documents), sections 1581–1592 (relating to peonage, slavery, and trafficking in persons).,1 sections 1831 and 1832 (relating to economic espionage and theft of trade secrets), section 1951 (relating to interference with commerce, robbery, or extortion), section 1952 (relating to racketeering), section 1953 (relating to interstate transportation of wagering paraphernalia), section 1954 (relating to unlawful welfare fund payments), section 1955 (relating to the prohibition of illegal gambling businesses), section 1956 (relating to the laundering of monetary instruments), section 1957 (relating to engaging in monetary transactions in property derived from specified unlawful activity), section 1958 (relating to use of interstate commerce facilities in the commission of murder-for-hire), section 1960 (relating to illegal money transmitters), sections 2251, 2251A, 2252, and 2260 (relating to sexual exploitation of children), sections 2312 and 2313 (relating to interstate transportation of stolen motor vehicles), sections 2314 and 2315 (relating to interstate transportation of stolen property), section 2318 (relating to trafficking in counterfeit labels for phonorecords, computer programs or computer program documentation or packaging and copies of motion pictures or other audiovisual works), section 2319 (relating to criminal infringement of a copyright), section 2319A (relating to unauthorized fixation of and trafficking in sound recordings and music videos of live musical performances), section 2320 (relating to trafficking in goods or services bearing counterfeit marks), section 2321 (relating to trafficking in certain motor vehicles or motor vehicle parts), sections 2341–2346 (relating to trafficking in contraband cigarettes), sections 2421–24 (relating to white slave traffic),2 sections 175–178 (relating to biological weapons), sections 229–229F (relating to chemical weapons), section 831 (relating to nuclear materials), (C) any act which is indictable under title 29, United States Code, section 186 (dealing with restrictions on payments and loans to labor organizations) or section 501(c) (relating to embezzlement from union funds), (D) any offense involving fraud connected with a case under title 11 (except a case under section 157 of this title), fraud in the sale of securities, or the felonious manufacture, importation, receiving, concealment, buying, selling, or otherwise dealing in a controlled substance or listed chemical (as defined in section 102 of the Controlled Substances Act), punishable under any law of the United States, (E) any act which is indictable under the Currency and Foreign Transactions Reporting Act, (F) any act which is indictable under the Immigration and Nationality Act, section 274 (relating to bringing in and harboring certain aliens), section 277 (relating to aiding or assisting certain aliens to enter the United States), or section 278 (relating to importation of alien for immoral purpose) if the act indictable under such section of such Act was committed for the purpose of financial gain, or (G) any act that is indictable under any provision listed in section 2332b(g)(5)(B);"],[1,"(2) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, any territory or possession of the United States, any political subdivision, or any department, agency, or instrumentality thereof;"],[1,"(3) \"person\" includes any individual or entity capable of holding a legal or beneficial interest in property;"],[1,"(4) \"enterprise\" includes any individual, partnership, corporation, association, or other legal entity, and any union or group of individuals associated in fact although not a legal entity;"],[1,"(5) \"pattern of racketeering activity\" requires at least two acts of racketeering activity, one of which occurred after the effective date of this chapter and the last of which occurred within ten years (excluding any period of imprisonment) after the commission of a prior act of racketeering activity;"],[1,"(6) \"unlawful debt\" means a debt (A) incurred or contracted in gambling activity which was in violation of the law of the United States, a State or political subdivision thereof, or which is unenforceable under State or Federal law in whole or in part as to principal or interest because of the laws relating to usury, and (B) which was incurred in connection with the business of gambling in violation of the law of the United States, a State or political subdivision thereof, or the business of lending money or a thing of value at a rate usurious under State or Federal law, where the usurious rate is at least twice the enforceable rate;"],[1,"(7) \"racketeering investigator\" means any attorney or investigator so designated by the Attorney General and charged with the duty of enforcing or carrying into effect this chapter;"],[1,"(8) \"racketeering investigation\" means any inquiry conducted by any racketeering investigator for the purpose of ascertaining whether any person has been involved in any violation of this chapter or of any final order, judgment, or decree of any court of the United States, duly entered in any case or proceeding arising under this chapter;"],[1,"(9) \"documentary material\" includes any book, paper, document, record, recording, or other material; and"],[1,"(10) \"Attorney General\" includes the Attorney General of the United States, the Deputy Attorney General of the United States, the Associate Attorney General of the United States, any Assistant Attorney General of the United States, or any employee of the Department of Justice or any employee of any department or agency of the United States so designated by the Attorney General to carry out the powers conferred on the Attorney General by this chapter. Any department or agency so designated may use in investigations authorized by this chapter either the investigative provisions of this chapter or the investigative power of such department or agency otherwise conferred by law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1961?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 4, 5","1":"1, 11"},"q":[{"src":"brief","b":1,"text":"include any individual or entity capable of holding a legal or beneficial interest in property.","cite":"18 U.S.C. § 1961(3)"}]},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","stext":{"head":"§1962. Prohibited activities","paras":[[0,"(a) It shall be unlawful for any person who has received any income derived, directly or indirectly, from a pattern of racketeering activity or through collection of an unlawful debt in which such person has participated as a principal within the meaning of section 2, title 18, United States Code, to use or invest, directly or indirectly, any part of such income, or the proceeds of such income, in acquisition of any interest in, or the establishment or operation of, any enterprise which is engaged in, or the activities of which affect, interstate or foreign commerce. A purchase of securities on the open market for purposes of investment, and without the intention of controlling or participating in the control of the issuer, or of assisting another to do so, shall not be unlawful under this subsection if the securities of the issuer held by the purchaser, the members of his immediate family, and his or their accomplices in any pattern or racketeering activity or the collection of an unlawful debt after such purchase do not amount in the aggregate to one percent of the outstanding securities of any one class, and do not confer, either in law or in fact, the power to elect one or more directors of the issuer."],[0,"(b) It shall be unlawful for any person through a pattern of racketeering activity or through collection of an unlawful debt to acquire or maintain, directly or indirectly, any interest in or control of any enterprise which is engaged in, or the activities of which affect, interstate or foreign commerce."],[0,"(c) It shall be unlawful for any person employed by or associated with any enterprise engaged in, or the activities of which affect, interstate or foreign commerce, to conduct or participate, directly or indirectly, in the conduct of such enterprise's affairs through a pattern of racketeering activity or collection of unlawful debt."],[0,"(d) It shall be unlawful for any person to conspire to violate any of the provisions of subsection (a), (b), or (c) of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1962?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5","1":"2, 12, 26","2":"13, 19"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","subs":["(c)"],"stext":{"head":"§1964. Civil remedies","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to prevent and restrain violations of section 1962 of this chapter by issuing appropriate orders, including, but not limited to: ordering any person to divest himself of any interest, direct or indirect, in any enterprise; imposing reasonable restrictions on the future activities or investments of any person, including, but not limited to, prohibiting any person from engaging in the same type of endeavor as the enterprise engaged in, the activities of which affect interstate or foreign commerce; or ordering dissolution or reorganization of any enterprise, making due provision for the rights of innocent persons."],[0,"(b) The Attorney General may institute proceedings under this section. Pending final determination thereof, the court may at any time enter such restraining orders or prohibitions, or take such other actions, including the acceptance of satisfactory performance bonds, as it shall deem proper."],[0,"(c) Any person injured in his business or property by reason of a violation of section 1962 of this chapter may sue therefor in any appropriate United States district court and shall recover threefold the damages he sustains and the cost of the suit, including a reasonable attorney's fee, except that no person may rely upon any conduct that would have been actionable as fraud in the purchase or sale of securities to establish a violation of section 1962. The exception contained in the preceding sentence does not apply to an action against any person that is criminally convicted in connection with the fraud, in which case the statute of limitations shall start to run on the date on which the conviction becomes final."],[0,"(d) A final judgment or decree rendered in favor of the United States in any criminal proceeding brought by the United States under this chapter shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding brought by the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1964?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 4, 10, 12, 18","1":"1-3, 9-15, 21, 24-26, 28-31, 36, 39-43","2":"1-3, 7, 9-10, 13-17, 19-20"},"q":[{"src":"brief","b":1,"text":"injured in his business or property by reason of a violation of § 1962.","cite":"18 U.S.C. § 1964(c)"},{"src":"brief","b":1,"text":"[a]ny person injured in his business or property by reason of a violation of section 1962.","cite":"18 U.S.C. § 1964(c)"}]},{"t":"usc","label":"22 U.S.C. § 1650-1650a","url":"https://www.law.cornell.edu/uscode/text/22/1650-1650a","by":{"0":"53"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)"],"by":{"0":"8"}},{"t":"rule","label":"Fed. R. Civ. P. 69","url":"https://www.law.cornell.edu/rules/frcp/rule_69","subs":["(a)(2)"],"by":{"0":"54","1":"34"},"q":[{"src":"brief","b":1,"text":"may obtain discovery from any person—including the judgment debtor.","cite":"Fed. R. Civ. P. 69"}]},{"t":"case","label":"Af-Cap Inc. v. Republic of Congo","cite":"383 F.3d 361","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/361/","by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"attaching a situs to intangible property is necessarily a legal fiction; therefore, the selection of a situs for intangibles must be context-specific, embodying a ‘common sense appraisal of the requirements of justice and convenience in particular conditions.’","cite":"383 F.3d 361, 371"}]},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"1":"12, 40","2":"4"}},{"t":"case","label":"Arellano v. McDonugh","cite":"143 S. Ct. 543","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/543/","sc":1,"by":{"1":"11"}},{"t":"case","label":"Bascunan v. Elsaca","cite":"927 F.3d 108","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/927/108/","by":{"1":"35","2":"11"}},{"t":"case","label":"Bread PAC v. Fed. Election Comm’n","cite":"455 U.S. 577","y":1982,"id":"1981/80-1481","sc":1,"by":{"1":"12","2":"4"}},{"t":"case","label":"Campbell v. Cuff-Rose Music, Inc.","cite":"510 U.S. 569","y":1994,"id":"1993/92-1292","sc":1,"by":{"1":"40"}},{"t":"case","label":"Culbertson v. Berryhill","cite":"139 S. Ct. 517","y":2019,"id":"2018/17-773","sc":1,"by":{"1":"11"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"142 S. Ct. 2228","y":2022,"id":"2021/19-1392","sc":1,"by":{"1":"14","2":"15"}},{"t":"case","label":"Frontera Res. Azrbaijan Corp. v. State Oil Co. of the Azrbaijan Republic","cite":"582 F.3d 393","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/582/393/","by":{"1":"41"}},{"t":"case","label":"Glencore Grain Rotterdam B.V. v. Shivnath Rai Harnarain Co.","cite":"284 F.3d 1114","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/284/1114/","by":{"1":"41, 42"}},{"t":"case","label":"Hetronic Int’l, Inc. v. Hetronic Germany GmbH","cite":"10 F.4th 1016","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/10/1016/","by":{"1":"19, 20","2":"16"}},{"t":"case","label":"Humphrey v. GlaxoSmithKline","cite":"805 F.3d 694","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/805/694/","by":{"1":"26, 27, 36, 37, 38"}},{"t":"case","label":"Jannus v. AFSCME, Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"by":{"1":"14","2":"15"}},{"t":"case","label":"Laurel Gardens, LLC v. McKenna","cite":"948 F.3d 105","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/948/105/","by":{"1":"42"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"by":{"1":"39"}},{"t":"case","label":"Millbrook v. United States","cite":"569 U.S. 50","y":2013,"id":"2012/11-10362","sc":1,"by":{"1":"11"}},{"t":"case","label":"Ministry of Def. & Support for the Armed Forces of the Islamic Rep. of Iran v. Cubic Def. Sys., Inc.","cite":"665 F.3d 1091","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1091/","by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"the judgment has the same force and effect of a judgment in a civil action and may be enforced by the means available to enforce any other judgment.","cite":"665 F.3d 1091, 1094 n.1"}]},{"t":"case","label":"Office Depot, Inc. v. Zuccarini","cite":"596 F.3d 696","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/696/","by":{"1":"35"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Trust","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"by":{"1":"12"}},{"t":"case","label":"Shuttlesworth v. Birmingham","cite":"394 U.S. 147","y":1969,"id":"1968/42","sc":1,"by":{"1":"8"}},{"t":"case","label":"Tatung Co. v. Shu Tze Hsu","cite":"217 F. Supp. 3d 1138","y":2016,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/217/1138/","by":{"1":"27"}},{"t":"case","label":"United States v. Pink","cite":"315 U.S. 203","y":1942,"id":"1940-1955/315us203","sc":1,"by":{"1":"8"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31","2":"8"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"1, 12"}},{"t":"rule","label":"Fed. R. Evid. 201","url":"https://www.law.cornell.edu/rules/fre/rule_201","by":{"1":"8, 24"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"1":"40"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"2":"15"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"by":{"2":"4, 14, 21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"`serves to protect against unintended clashes between our laws and those of other nations which could result in international discord.'","cite":"569 U. S. 108, 115"},{"src":"argument","who":"Mr. Kennedy","text":"RJR focus -- applied the presumption against extraterritoriality, just as Morrison did, just as Kiobel did. That's always been conduct-focused."},{"src":"argument","who":"Mr. Kennedy","text":"That is the exact same test that was set forth in RJR Nabisco when looking at extraterritoriality, and it's the test this Court has used consistently, Kiobel, Nestle, going back to Morrison, looking at the statute that is the --"}]},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"by":{"2":"14"}},{"t":"const","label":"Article IV, Section 1","clauses":[["full-faith-credit","Full Faith and Credit Clause"]],"text":"Full Faith and Credit shall be given in each State to the public Acts, Records, and judicial Proceedings of every other State. And the Congress may by general Laws prescribe the Manner in which such Acts, Records and Proceedings shall be proved, and the Effect thereof.","by":{"2":"12"}},{"t":"usc","label":"28 U.S.C. § 1738","url":"https://www.law.cornell.edu/uscode/text/28/1738","by":{"2":"12"}},{"t":"usc","label":"28 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/28/1963","by":{"2":"12"}}]};